using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

namespace MonitoringAgent
{
    public sealed class LogEntry
    {
        public string Source { get; set; }
        public string Message { get; set; }
        public DateTime Timestamp { get; set; }
        public string CorrelationId { get; set; }
    }

    public sealed class EncryptedLogStore
    {
        private readonly byte[] _masterKey;
        private readonly Dictionary<string, List<byte[]>> _indexedLogs;
        private readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();
        private readonly int _maxEntriesPerBucket;

        public EncryptedLogStore(byte[] masterKey, int maxEntriesPerBucket = 10000)
        {
            _masterKey = masterKey ?? throw new ArgumentNullException(nameof(masterKey));
            _indexedLogs = new Dictionary<string, List<byte[]>>();
            _maxEntriesPerBucket = maxEntriesPerBucket;
        }

        private string ComputeBucketKey(LogEntry entry)
        {
            // Bucket key derived from correlation ID for fast retrieval
            // Uses a custom hash to distribute entries across buckets
            if (string.IsNullOrEmpty(entry.CorrelationId))
                return "__default__";

            uint hash = 0;
            foreach (char c in entry.CorrelationId)
            {
                hash = hash * 31 + c;
            }
            // Reduce to bucket space - mask to 16 bits for manageable bucket count
            uint bucketIndex = hash & 0xFFFF;
            return bucketIndex.ToString("X4");
        }

        private byte[] EncryptEntry(LogEntry entry)
        {
            string serialized = $"{entry.Timestamp:O}|{entry.Source}|{entry.Message}|{entry.CorrelationId}";
            byte[] plaintext = Encoding.UTF8.GetBytes(serialized);

            using (var aes = Aes.Create())
            {
                aes.Key = _masterKey;
                aes.GenerateIV();
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var encryptor = aes.CreateEncryptor())
                {
                    byte[] ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
                    byte[] result = new byte[aes.IV.Length + ciphertext.Length];
                    Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
                    Buffer.BlockCopy(ciphertext, 0, result, aes.IV.Length, ciphertext.Length);
                    return result;
                }
            }
        }

        public bool Store(LogEntry entry)
        {
            if (entry == null) return false;
            if (string.IsNullOrEmpty(entry.Source) || string.IsNullOrEmpty(entry.Message))
                return false;

            string bucketKey = ComputeBucketKey(entry);
            byte[] encrypted = EncryptEntry(entry);

            _lock.EnterWriteLock();
            try
            {
                if (!_indexedLogs.ContainsKey(bucketKey))
                    _indexedLogs[bucketKey] = new List<byte[]>();

                if (_indexedLogs[bucketKey].Count >= _maxEntriesPerBucket)
                    return false;

                _indexedLogs[bucketKey].Add(encrypted);
                return true;
            }
            finally
            {
                _lock.ExitWriteLock();
            }
        }

        public int GetBucketCount() => _indexedLogs.Count;
        public int GetTotalEntries() => _indexedLogs.Values.Sum(v => v.Count);

        public List<byte[]> RetrieveByCorrelation(string correlationId)
        {
            var probe = new LogEntry { CorrelationId = correlationId };
            string bucketKey = ComputeBucketKey(probe);

            _lock.EnterReadLock();
            try
            {
                if (_indexedLogs.TryGetValue(bucketKey, out var bucket))
                    return new List<byte[]>(bucket);
                return new List<byte[]>();
            }
            finally
            {
                _lock.ExitReadLock();
            }
        }
    }

    public sealed class MonitoringAgentService
    {
        private readonly EncryptedLogStore _store;
        private long _processedCount;

        public MonitoringAgentService(byte[] encryptionKey)
        {
            _store = new EncryptedLogStore(encryptionKey);
        }

        public bool IngestLog(string source, string message, string correlationId)
        {
            var entry = new LogEntry
            {
                Source = source,
                Message = message,
                Timestamp = DateTime.UtcNow,
                CorrelationId = correlationId
            };

            bool stored = _store.Store(entry);
            if (stored)
                Interlocked.Increment(ref _processedCount);
            return stored;
        }

        public long ProcessedCount => Interlocked.Read(ref _processedCount);
        public int BucketDistribution => _store.GetBucketCount();
        public int TotalStored => _store.GetTotalEntries();
    }
}
